contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint w) public payable {
        require(address(this).balance >= amount);
        // fund c via sendMoney targeting c itself, which hits c's fallback and accepts ether
        c.sendMoney(address(c), amount);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdraw(w) { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        if (w <= balBefore) {
            assert(!reverted && balAfter == balBefore - w);
        } else {
            assert(reverted && balAfter == balBefore);
        }
    }
    receive() external payable {}
}

